const $=id=>document.getElementById(id);
let user=null,rows=[],editing=null,page='Dashboard';
const domains=['Jaringan','Server & Virtualisasi','Keamanan','Backup & Recovery','Data Center','Monitoring'];
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const admin=()=>user&&user.role==='Admin',writer=()=>user&&['Admin','Assessor'].includes(user.role);
async function api(p,o){
 const r=await fetch('/api'+p,Object.assign({credentials:'same-origin',headers:{'content-type':'application/json'}},o||{}));
 const raw=await r.text();let d={};
 try{d=raw?JSON.parse(raw):{}}catch(parseError){console.error('Non-JSON API response:',r.status,raw);throw Error('Server API mengembalikan respons tidak valid (HTTP '+r.status+').')}
 if(!r.ok)throw Error(d.error||('Permintaan gagal (HTTP '+r.status+').'));
 return d
}
function toast(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3500)}
async function login(msg){
let x=document.getElementById('auth-layer');if(!x){x=document.createElement('div');x.id='auth-layer';document.body.append(x)}
$('shell').setAttribute('aria-hidden','true');
let needsSetup=false;try{needsSetup=(await api('/setup/status')).needsSetup===true}catch(e){}
if(needsSetup){
x.innerHTML='<section class="auth-card"><div class="eyebrow">PT BORNEO ALUMINA INDONESIA</div><div class="auth-logo">bai<span>▪</span></div><h1>Gap Analysis System</h1><p>Belum ada akun Administrator. Buat akun Administrator pertama untuk mengaktifkan aplikasi.</p><div id="login-error" class="auth-error">'+esc(msg||'')+'</div><button type="button" class="primary" id="show-admin-register">＋ Daftar Administrator</button><small>Pendaftaran hanya tersedia satu kali selama database belum memiliki akun.</small></section>';
$('show-admin-register').onclick=()=>{
x.innerHTML='<form id="bootstrap-form" class="auth-card"><div class="eyebrow">PT BORNEO ALUMINA INDONESIA</div><div class="auth-logo">bai<span>▪</span></div><h1>Daftar Administrator</h1><p>Buat akun Administrator pertama. Secret diverifikasi langsung oleh Cloudflare Worker dan tidak disimpan di browser.</p><div id="login-error" class="auth-error"></div><label>Username<input name="username" autocomplete="username" required maxlength="60"></label><label>Nama Administrator<input name="displayName" autocomplete="name" required maxlength="120"></label><label>Password Administrator<input name="password" type="password" autocomplete="new-password" required minlength="12" maxlength="128"></label><label>Cloudflare Bootstrap Secret<input name="bootstrapSecret" type="password" autocomplete="off" required maxlength="256"></label><button class="primary">Buat Administrator pertama</button><button type="button" id="cancel-admin-register">Kembali</button><small>Secret harus sama dengan BOOTSTRAP_SECRET di Cloudflare Worker. Hapus secret setelah akun berhasil dibuat.</small></form>';
$('cancel-admin-register').onclick=()=>login();
$('bootstrap-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,submit=form.querySelector('button[type="submit"],button:not([type])'),b=Object.fromEntries(new FormData(form));submit.disabled=true;submit.textContent='Memproses...';try{await api('/setup/admin',{method:'POST',body:JSON.stringify(b)});form.reset();login('Administrator berhasil dibuat. Silakan masuk.')}catch(err){$('login-error').textContent=err.message;submit.disabled=false;submit.textContent='Buat Administrator pertama'}};
};return;
}
x.innerHTML='<form id="login-form" class="auth-card"><div class="eyebrow">PT BORNEO ALUMINA INDONESIA</div><div class="auth-logo">bai<span>▪</span></div><h1>Gap Analysis System</h1><p>Masuk menggunakan akun aplikasi Anda.</p><div id="login-error" class="auth-error">'+esc(msg||'')+'</div><label>Username<input name="username" autocomplete="username" required maxlength="60"></label><label>Password<input name="password" type="password" autocomplete="current-password" required maxlength="128"></label><button class="primary">Masuk ke aplikasi</button><small>Akses hanya untuk pengguna yang telah didaftarkan Administrator.</small></form>';
$('login-form').onsubmit=async e=>{e.preventDefault();let b=Object.fromEntries(new FormData(e.target));try{let d=await api('/auth/login',{method:'POST',body:JSON.stringify(b)});user=d.user;x.remove();$('shell').removeAttribute('aria-hidden');await init()}catch(err){$('login-error').textContent=err.message}};
}
async function init(){try{rows=(await api('/gaps')).data||[];$('user-name').textContent=user.displayName;$('user-role').textContent=user.role;$('period').textContent='PENGGUNA · '+user.displayName.toUpperCase();$('addAssessment').hidden=!writer();$('noticeTitle').textContent='Sistem aktif';$('noticeText').textContent='Data tersimpan terpusat dan dapat diakses sesuai hak pengguna.';domains.forEach(d=>{if(!$('domain').querySelector('option[value="'+d+'"]'))$('domain').add(new Option(d,d))});if(admin()){let n=document.querySelector('aside nav');n.insertAdjacentHTML('beforeend','<button data-page="Pengguna">♙ <span>Pengguna</span></button><button data-page="Audit Log">◷ <span>Audit Log</span></button>')}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.page));render();navigate('Dashboard')}catch(e){toast(e.message)}}
function navigate(p){page=p;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('crumb').textContent=p;$('title').textContent=p==='Dashboard'?'Dashboard Infrastruktur':p;$('dashboard').hidden=p!=='Dashboard';$('report').hidden=p!=='Laporan';$('register').hidden=['Laporan','Pengguna','Audit Log'].includes(p);if(p==='Pengguna'||p==='Audit Log')adminPage();else render()}
function render(){let open=rows.filter(r=>r.status!=='Selesai'),a=rows.length?rows.reduce((s,r)=>s+Number(r.actual),0)/rows.length:0,t=rows.length?rows.reduce((s,r)=>s+Number(r.target),0)/rows.length:0,ready=t?Math.round(a/t*100):0;
$('stats').innerHTML=[['Kesiapan infrastruktur',ready+'%','Skor aktual '+a.toFixed(1)+' dari target '+t.toFixed(1),'◈'],['Total assessment',rows.length,'Domain '+new Set(rows.map(r=>r.domain)).size,'▤'],['Gap prioritas kritis',open.filter(r=>r.priority==='Kritis').length,'Memerlukan perhatian segera','⚑'],['Perbaikan selesai',rows.filter(r=>r.status==='Selesai').length,'Dari '+rows.length+' rencana perbaikan','✓']].map(x=>'<div class="stat"><div class="label">'+x[0]+'<span>'+x[3]+'</span></div><b>'+x[1]+'</b><small>'+x[2]+'</small></div>').join('');
$('bars').innerHTML=domains.map(d=>{let q=rows.filter(r=>r.domain===d),v=q.length?q.reduce((s,r)=>s+ +r.actual,0)/q.length:0,z=q.length?q.reduce((s,r)=>s+ +r.target,0)/q.length:0;return '<div class="barrow"><span>'+d+'</span><div class="track" style="width:'+(z/5*100)+'%"><i style="width:'+(z?v/z*100:0)+'%"></i></div><b>'+v.toFixed(1)+' / '+z.toFixed(1)+'</b></div>'}).join('');
let gap=rows.filter(r=>r.target>r.actual),cols={Kritis:'#c76a54',Tinggi:'#d3a35b',Sedang:'#71a798',Rendah:'#a9c6d0'},start=0,slices=[];Object.keys(cols).forEach(k=>{let n=gap.filter(r=>r.priority===k).length,end=start+(gap.length?n/gap.length*100:0);slices.push(cols[k]+' '+start+'% '+end+'%');start=end});$('gapcount').textContent=gap.length;$('donut').style.background=gap.length?'conic-gradient('+slices.join(',')+')':'#e3eeea';$('priorities').innerHTML=Object.keys(cols).map(k=>'<div class="priorityline"><span><i style="background:'+cols[k]+'"></i>'+k+'</span><b>'+gap.filter(r=>r.priority===k).length+' <span>gap</span></b></div>').join('');
let q=rows.filter(r=>(!$('domain').value||r.domain===$('domain').value)&&(!$('priority').value||r.priority===$('priority').value)&&((r.title+' '+r.owner+' '+(r.actual_condition||'')+' '+(r.ideal_condition||'')).toLowerCase().includes($('search').value.toLowerCase()))&&(page!=='Rencana Aksi'||r.status!=='Selesai'));
$('rows').innerHTML=q.map(r=>'<tr><td><strong>'+esc(r.title)+'</strong><small>'+esc(r.domain)+' · '+esc(r.id.slice(0,8))+'</small></td><td class="condition-cell">'+esc(r.actual_condition||'Belum diisi')+'</td><td class="condition-cell">'+esc(r.ideal_condition||'Belum diisi')+'</td><td>'+r.actual+' → '+r.target+'</td><td><b>'+Math.max(0,r.target-r.actual).toFixed(1)+'</b></td><td><span class="badge '+r.priority+'">'+r.priority+'</span></td><td>'+esc(r.owner)+'<small>'+esc(r.due)+'</small></td><td><span class="status">● '+esc(r.status)+'</span></td><td>'+(writer()?'<button data-id="'+esc(r.id)+'" title="Ubah temuan">↗</button> <button data-delete-id="'+esc(r.id)+'" title="Hapus temuan">Hapus</button>':'—')+'</td></tr>').join('')||'<tr><td colspan="9">Belum ada assessment atau tidak ada hasil filter.</td></tr>';
$('recordcount').textContent=rows.length+' assessment';$('shown').textContent='Menampilkan '+q.length+' dari '+rows.length+' assessment';$('report').innerHTML='<article><div class="eyebrow">RINGKASAN ASSESSMENT</div><h1>Laporan Kesiapan Infrastruktur</h1><p>'+rows.length+' assessment • Kesiapan '+ready+'% • '+open.length+' rencana belum selesai</p><p>Skor kesiapan = total skor aktual ÷ total skor target × 100%.</p><button onclick="exportCSV()">↓ Unduh laporan CSV</button></article>'}
function openForm(id){if(!writer())return;editing=id||null;$('form').reset();let r=rows.find(x=>x.id===id);$('formtitle').textContent=r?'Ubah assessment':'Tambah assessment';$('deletebtn').hidden=false;$('deletebtn').disabled=!r;$('deletebtn').title=r?'Hapus temuan ini':'Simpan assessment terlebih dahulu sebelum dapat dihapus';if(r)Object.keys(r).forEach(k=>{if($('form').elements[k])$('form').elements[k].value=r[k]});else{$('form').elements.actual.value=1;$('form').elements.target.value=5}$('editor').showModal()}
async function removeRecord(){if(!writer()||!editing||!confirm('Hapus temuan ini secara permanen? Tindakan ini tidak dapat dibatalkan.'))return;try{await api('/gaps/'+encodeURIComponent(editing),{method:'DELETE'});$('editor').close();editing=null;rows=(await api('/gaps')).data;render();toast('Temuan berhasil dihapus.')}catch(e){toast(e.message)}}
async function removeRow(id){if(!writer()||!id||!confirm('Hapus temuan ini secara permanen? Tindakan ini tidak dapat dibatalkan.'))return;try{await api('/gaps/'+encodeURIComponent(id),{method:'DELETE'});rows=(await api('/gaps')).data;render();toast('Temuan berhasil dihapus.')}catch(e){toast(e.message)}}
async function saveForm(e){e.preventDefault();let b=Object.fromEntries(new FormData(e.target));b.actual=+b.actual;b.target=+b.target;if(b.actual>b.target)return toast('Target harus sama atau lebih tinggi dari skor aktual.');try{await api(editing?'/gaps/'+encodeURIComponent(editing):'/gaps',{method:editing?'PUT':'POST',body:JSON.stringify(b)});$('editor').close();rows=(await api('/gaps')).data;render();toast('Assessment tersimpan ke database.')}catch(e){toast(e.message)}}
function exportCSV(){let keys=['id','title','domain','actual_condition','ideal_condition','actual','target','priority','owner','due','action','status'],cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"',csv='\uFEFF'+[keys.join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n'),u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='BAI-gap-analysis.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function adminPage(){let old=document.getElementById('admin-area');if(old)old.remove();let area=document.createElement('section');area.id='admin-area';area.style.marginTop='22px';$('register').after(area);if(page==='Pengguna'){area.innerHTML='<article><div class="cardhead"><div><h2>Manajemen pengguna</h2><p>Kelola akun dan hak akses</p></div><button class="primary" id="new-user">＋ Tambah pengguna</button></div><div class="tablewrap"><table><thead><tr><th>USERNAME</th><th>NAMA</th><th>ROLE</th><th>STATUS</th><th>AKSI</th></tr></thead><tbody id="user-rows"></tbody></table></div></article>';try{let d=await api('/users');$('user-rows').innerHTML=d.data.map(u=>'<tr><td>'+esc(u.username)+'</td><td>'+esc(u.displayName)+'</td><td><select data-role="'+u.id+'"><option '+(u.role==='Admin'?'selected':'')+'>Admin</option><option '+(u.role==='Assessor'?'selected':'')+'>Assessor</option><option '+(u.role==='Viewer'?'selected':'')+'>Viewer</option></select></td><td>'+(u.active?'Aktif':'Nonaktif')+'</td><td>'+(u.id===user.id?'Akun Anda':'<button data-save="'+u.id+'">Simpan role</button> <button data-disable="'+u.id+'">Nonaktifkan</button>')+'</td></tr>').join('');area.querySelectorAll('[data-save]').forEach(b=>b.onclick=async()=>{let id=b.dataset.save,role=area.querySelector('[data-role="'+id+'"]').value;try{await api('/users/'+id,{method:'PATCH',body:JSON.stringify({role:role,active:true})});toast('Role diperbarui')}catch(e){toast(e.message)}});area.querySelectorAll('[data-disable]').forEach(b=>b.onclick=async()=>{if(!confirm('Nonaktifkan akun ini?'))return;try{await api('/users/'+b.dataset.disable,{method:'DELETE'});adminPage();toast('Akun dinonaktifkan')}catch(e){toast(e.message)}});$('new-user').onclick=()=>newUser()}catch(e){area.innerHTML='<article>'+esc(e.message)+'</article>'}}else{area.innerHTML='<article><div class="cardhead"><div><h2>Audit log</h2><p>Aktivitas pengguna terbaru</p></div></div><div class="tablewrap"><table><thead><tr><th>WAKTU</th><th>PENGGUNA</th><th>AKTIVITAS</th><th>OBJEK</th><th>DETAIL</th></tr></thead><tbody id="audit-rows"></tbody></table></div></article>';try{let d=await api('/audit');$('audit-rows').innerHTML=d.data.map(x=>'<tr><td>'+esc(x.createdAt)+'</td><td>'+esc(x.username)+'</td><td>'+esc(x.action)+'</td><td>'+esc(x.entity)+' '+esc(x.entityId)+'</td><td>'+esc(x.details)+'</td></tr>').join('')}catch(e){area.innerHTML='<article>'+esc(e.message)+'</article>'}}}
function newUser(){let d=document.createElement('dialog');d.className='user-dialog';d.innerHTML='<form id="new-user-form"><h2>Tambah pengguna</h2><label>Username<input name="username" required maxlength="60"></label><label>Nama lengkap<input name="displayName" required maxlength="120"></label><label>Password awal (minimal 12 karakter)<input name="password" type="password" required minlength="12"></label><label>Role<select name="role"><option>Assessor</option><option>Viewer</option><option>Admin</option></select></label><div class="formactions"><button type="button" id="cancel-user">Batal</button><button class="primary">Buat akun</button></div></form>';document.body.append(d);d.showModal();$('cancel-user').onclick=()=>{d.close();d.remove()};$('new-user-form').onsubmit=async e=>{e.preventDefault();try{await api('/users',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});d.close();d.remove();adminPage();toast('Akun berhasil dibuat')}catch(x){toast(x.message)}}}
$('form').onsubmit=saveForm;$('rows').onclick=e=>{let del=e.target.closest('[data-delete-id]');if(del){removeRow(del.dataset.deleteId);return}let b=e.target.closest('[data-id]');if(b)openForm(b.dataset.id)};['search','domain','priority'].forEach(id=>$(id).addEventListener('input',render));$('addAssessment').onclick=()=>openForm();document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.page));user={id:'public-workspace',username:'workspace',displayName:'Workspace',role:'Assessor'};init().catch(e=>toast(e.message));
